<script setup>
import {onBeforeUnmount,onMounted,ref} from 'vue'
import {apiGet,apiRequest} from '../services/api.js'
import {formatarDataHora} from '../utils/format.js'
const emit=defineEmits(['updated']),phone=ref(null),busy=ref(false),error=ref(''),notice=ref(''),mode=ref('')
const barriers=[['schedule','Horário ou turno'],['transport','Transporte'],['attendance_prize','Medo de perder hora ou assiduidade'],['unnecessary','Não vejo necessidade'],['other','Outro motivo']]
async function load(){try{phone.value=await apiGet('/demo/outreach/phone')}catch(e){error.value=e.message}}
async function reply(choice,extra={}){busy.value=true;error.value='';try{const result=await apiRequest('/demo/outreach/reply','POST',{choice,...extra});phone.value=result.phone;notice.value=result.message;mode.value='';emit('updated');window.dispatchEvent(new Event('elo-channel-updated'))}catch(e){error.value=e.message}finally{busy.value=false}}
function speak(){if(!('speechSynthesis'in window)){error.value='Áudio indisponível neste navegador. Use Preciso de apoio.';return}speechSynthesis.cancel();const s=new SpeechSynthesisUtterance(message()+' Para confirmar, toque no botão verde. Para outro horário, toque em Preciso remarcar.');s.lang='pt-BR';s.rate=.85;speechSynthesis.speak(s)}
function message(){return phone.value?'Olá, Marcos. Aqui é a sua equipe de saúde do SESI. Seu retorno está marcado para '+formatarDataHora(phone.value.scheduled_at)+', na '+phone.value.unit+'. Ele serve para acompanhar o plano que você combinou com a enfermeira. Você pode responder com um toque.':''}
onMounted(load);onBeforeUnmount(()=>{if('speechSynthesis'in window)speechSynthesis.cancel()})
</script>
<template><section class="marcos-phone mx-auto" data-demo="msg-marcos"><header><strong>Equipe de saúde · SESI</strong><small>Simulação do WhatsApp</small></header><div class="phone-body"><p v-if="error" class="alert alert-danger">{{error}}</p><p v-if="!phone&&!error">Carregando mensagem…</p><template v-if="phone"><p class="message">{{message()}}</p><button class="btn btn-light w-100 mb-2" @click="speak">▶ Ouvir mensagem</button><p v-if="notice" class="alert alert-success" role="status">{{notice}}</p><p v-if="phone.state==='confirmed'" class="badge text-bg-success">Confirmado</p><p v-if="phone.state==='rescheduled'" class="badge text-bg-success">Reagendado · {{formatarDataHora(phone.scheduled_at)}}</p><div class="d-grid gap-2"><button data-demo="btn-confirmo" class="btn btn-success btn-lg" :disabled="busy" @click="reply('confirm')">✓ Confirmo</button><button data-demo="btn-remarcar" class="btn btn-light btn-lg" :disabled="busy" @click="mode=mode==='slots'?'':'slots'">↻ Preciso remarcar</button><button data-demo="btn-nao-posso" class="btn btn-light btn-lg" :disabled="busy" @click="mode=mode==='barriers'?'':'barriers'">Não posso ir</button></div><section v-if="mode==='slots'" class="message mt-3"><h2 class="h6">Escolha depois do turno das 6h às 14h</h2><button v-for="slot in phone.slots" :key="slot.id" class="btn btn-outline-success w-100 mb-2" :disabled="busy" @click="reply('reschedule',{slot_id:Number(slot.id)})">{{formatarDataHora(slot.starts_at)}} · {{slot.unit}}</button><p v-if="!phone.slots.length">Sem horário compatível. Peça apoio à equipe.</p></section><section v-if="mode==='barriers'" class="message mt-3"><h2 class="h6">Se quiser, conte o que dificulta</h2><button v-for="[key,text] in barriers" :key="key" class="btn btn-outline-success w-100 mb-2" :disabled="busy" @click="reply('cannot',{barrier:key})">{{text}}</button></section><button class="btn btn-link w-100 mt-2" :disabled="busy" @click="reply('support')">Preciso de apoio</button><p class="small mb-0">O que você conta à equipe de saúde fica com ela. Seu líder e a empresa não veem.</p></template></div></section></template>
<style scoped>.marcos-phone{max-width:375px;border:6px solid #234340;border-radius:22px;overflow:hidden}.marcos-phone header{background:#086452;color:white;padding:14px}.marcos-phone header small{display:block}.phone-body{padding:12px;background:#eae5dd}.message{padding:14px;background:white;border-radius:10px}.btn{white-space:normal}</style>
